import React, { useEffect, useState } from "react";
import axios from "axios";
import "./dashboard.css";

function Planner() {
  const userId = localStorage.getItem("user_id");

  const [plans, setPlans] = useState([]);
  const [courses, setCourses] = useState([]);
  const [form, setForm] = useState({
    course_id: "",
    study_date: "",
    topic: ""
  });

  const loadData = async () => {
    const res = await axios.get(`http://127.0.0.1:8000/planner/${userId}`);
    setPlans(res.data.plans || []);

    const c = await axios.get("http://127.0.0.1:8000/courses");
    const e = await axios.get(`http://127.0.0.1:8000/enrollments/${userId}`);

    const ids = e.data.map(i => i.course_id);

    setCourses((c.data.courses || []).filter(x => ids.includes(x.id)));
  };

  useEffect(() => {
    loadData();
  }, []);

  const createManualPlan = async (e) => {
    e.preventDefault();

    await axios.post("http://127.0.0.1:8000/create-plan", {
      user_id: parseInt(userId),
      course_id: parseInt(form.course_id),
      study_date: form.study_date,
      topic: form.topic
    });

    setForm({ course_id: "", study_date: "", topic: "" });
    loadData();
  };

  const completePlan = async (id) => {
    await axios.put(`http://127.0.0.1:8000/complete-plan/${id}`);
    loadData();
  };

  const generateSmartPlan = async () => {
    await axios.post(`http://127.0.0.1:8000/smart-auto-plan/${userId}`);
    loadData();
  };

  return (
    <div>
      <h2>📅 Smart Planner</h2>

      <button className="btn btn-primary" onClick={generateSmartPlan}>
        Generate Smart Plan
      </button>

      {/* MANUAL PLAN */}
      <div className="section-card">
        <h3>Create Manual Plan</h3>

        <form onSubmit={createManualPlan}>
          <select
            className="input"
            value={form.course_id}
            onChange={(e) => setForm({ ...form, course_id: e.target.value })}
          >
            <option value="">Select Course</option>
            {courses.map(c => (
              <option key={c.id} value={c.id}>{c.title}</option>
            ))}
          </select>

          <input
            className="input"
            type="date"
            value={form.study_date}
            onChange={(e) => setForm({ ...form, study_date: e.target.value })}
          />

          <input
            className="input"
            placeholder="Topic"
            value={form.topic}
            onChange={(e) => setForm({ ...form, topic: e.target.value })}
          />

          <button className="btn btn-primary">Create Plan</button>
        </form>
      </div>

      {/* PLAN LIST */}
      <div className="section-card">
        <h3>My Plans</h3>

        {plans.map(p => {
          const isExpired = p.status === "Expired";

          return (
            <div className="list-card" key={p.id}>
              <h4>{p.topic}</h4>
              <div>{p.study_date}</div>

              <div>
                {p.status === "Completed" && (
                  <span className="badge badge-green">Completed</span>
                )}

                {isExpired && (
                  <span className="badge badge-orange">Expired</span>
                )}

                {p.status === "Pending" && !isExpired && (
                  <span className="badge badge-purple">Pending</span>
                )}
              </div>

              {!isExpired && p.status === "Pending" && (
                <button
                  className="btn btn-primary"
                  onClick={() => completePlan(p.id)}
                >
                  Mark Done
                </button>
              )}
            </div>
          );
        })}
      </div>
    </div>
  );
}

export default Planner;
